INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92458,0,0,'Patricia! Would you be so kind as to show our friend here the newest recipes we\'ve discovered?',12,0,100.0,1,0,0,98778,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92458,1,1,'Let\'s try the recipe for this "Draught of Wild Magic", shall we?',12,0,100.0,1,0,0,97202,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92458,3,3,'You should talk to Patricia. I believe she can offer you a new recipe.',12,0,100.0,1,0,0,98208,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92458,4,4,'Nicely done! Patricia has a new recipe for you, $n.',12,0,100.0,1,0,0,97051,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92458,5,5,'Excellent work. Speak to Patricia about a new recipe.',12,0,100.0,1,0,0,98207,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92458,6,6,'Join me over here, $n. I believe we have some of the reagents here on this shelf.',12,0,100.0,1,0,0,97203,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92458,7,7,'We\'ll be fine, Archmage, but... look what that wretched creature did to my alchemy table!',12,0,100.0,1,0,0,97209,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92458,9,9,'Ah yes, I have one right here. Now be VERY careful with that. Spilling a drop of it can result in, well, unfortunate results.',12,0,0.0,0,0,0,104734,0,'LegionCore');
