INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92539,0,0,'In Haustvald, the Bonespeakers keep the dead. They will not help you.',12,0,100.0,0,0,0,98443,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92539,1,0,'Their ways are twisted. They have forgotten the old vows.',12,0,100.0,0,0,0,98444,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92539,2,0,'But there is one who remembers. One who is rooted in the old ways.',12,0,100.0,0,0,0,98445,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92539,3,0,'Seek Vydhar! Earn your judgment, and pass the Trial of Valor.',12,0,100.0,0,0,0,98446,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92539,4,0,'For aeons, Helya has been building an army. Stealing the souls of fallen vrykul to oppose the Valarjar.',12,0,100.0,0,0,78317,123440,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92539,5,0,'I suspect the sea witch grows impatient, eager to begin her campaign by conquering the Broken Isles.',12,0,100.0,0,0,78319,123494,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92539,6,0,'Helya\'s foul magics trap Odyn and hinder the Valarjar. We need champions like you to stop her advances.',12,0,100.0,0,0,78320,123495,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92539,7,0,'Helya must be stopped. The time has come for a reckoning!',12,0,100.0,0,0,78321,123496,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92539,8,0,'How dare she so brashly oppose me!',12,0,100.0,0,0,78318,123454,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92539,9,0,'I have had enough of that foul sorceress\' games!',14,0,100.0,0,0,77637,123497,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92539,10,0,'That sea witch must learn the price of her defiance!',12,0,100.0,0,0,78208,123498,0,'LegionCore');
