INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93520,0,0,'I\'ll get started on fixin\' it up with stuff I have around the shop.',12,0,100.0,1,0,0,105602,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93520,1,0,'Flashy, but ineffective. We\'ll have to try something else. Maybe we need a chemical reaction.',12,0,100.0,1,0,0,104805,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93520,2,0,'Go to the alchemy shop and ask Deucus for a potion with some punch in it.',12,0,100.0,1,0,0,104806,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93520,3,0,'Alright, I\'m going to pour in the solution now. Watch yourself, not sure how this is going to react.',12,0,100.0,0,0,0,104807,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93520,4,0,'Are you alright? *Cough, cough* I\'m thinking the only thing that\'s going to work here is a fel-infused core.',12,0,100.0,1,0,0,104808,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93520,5,0,'It\'s a long shot, but there may be someone here in Dalaran who has one. Try asking Bonegrim in the Ledgerdemain Lounge if he\'s come across any.',12,0,100.0,1,0,0,104809,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93520,6,0,'You found something?! That\'s amazing! You\'re amazing, $n! Keep your fingers crossed, I\'m gonna put it in now.',12,0,100.0,0,0,0,104810,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93520,7,0,'Success!',12,0,100.0,4,0,0,122294,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93520,8,0,'Sure thing. They\'re right over there on that table. They\'ve been working out great!',12,0,100.0,1,0,0,102675,0,'LegionCore');
