INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (93526,5,5,'I suppose I can part with one. But tell Didi I\'m sending her a bill for it. We\'re not running a charity here.',12,0,0.0,0,0,0,104692,0,'LegionCore');
