INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96198,0,0,'Excuse me, but that\'s my jewel. Could you please leave it alone?',12,0,100.0,1,0,0,104779,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96198,2,0,'Oh, well then I\'ll be right down. Coming!',12,0,100.0,1,0,0,104781,0,'LegionCore');
