INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (96198,4,0,'I wonder where they went to. Oh well, perhaps they\'ll come back.',12,0,100.0,1,0,0,104784,0,'LegionCore');
