INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (104728,3,0,'Shala\'nir is just ahead. You should be ready for whatever foulness awaits us.',12,0,100.0,0,0,0,107929,0,'LegionCore');
